use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclfn! {
# [doc = " Returns true if the given character can be escaped in a regex."] # [doc = ""] # [doc = " This returns true in all cases that `is_meta_character` returns true, but"] # [doc = " also returns true in some cases where `is_meta_character` returns false."] # [doc = " For example, `%` is not a meta character, but it is escapable. That is,"] # [doc = " `%` and `\\%` both match a literal `%` in all contexts."] # [doc = ""] # [doc = " The purpose of this routine is to provide knowledge about what characters"] # [doc = " may be escaped. Namely, most regex engines permit \"superfluous\" escapes"] # [doc = " where characters without any special significance may be escaped even"] # [doc = " though there is no actual _need_ to do so."] # [doc = ""] # [doc = " This will return false for some characters. For example, `e` is not"] # [doc = " escapable. Therefore, `\\e` will either result in a parse error (which is"] # [doc = " true today), or it could backwards compatibly evolve into a new construct"] # [doc = " with its own meaning. Indeed, that is the purpose of banning _some_"] # [doc = " superfluous escapes: it provides a way to evolve the syntax in a compatible"] # [doc = " manner."] # [doc = ""] # [doc = " # Example"] # [doc = ""] # [doc = " ```"] # [doc = " use regex_syntax::is_escapeable_character;"] # [doc = ""] # [doc = " assert!(is_escapeable_character('?'));"] # [doc = " assert!(is_escapeable_character('-'));"] # [doc = " assert!(is_escapeable_character('&'));"] # [doc = " assert!(is_escapeable_character('#'));"] # [doc = " assert!(is_escapeable_character('%'));"] # [doc = " assert!(is_escapeable_character('/'));"] # [doc = " assert!(is_escapeable_character('!'));"] # [doc = " assert!(is_escapeable_character('\"'));"] # [doc = ""] # [doc = " assert!(!is_escapeable_character('e'));"] # [doc = " ```"] pub fn is_escapeable_character (c : char) -> bool { if is_meta_character (c) { return true ; } if ! c . is_ascii () { return false ; } match c { '0' ..= '9' | 'A' ..= 'Z' | 'a' ..= 'z' => false , '<' | '>' => false , _ => true , } }
}